  bottom: -1px;
  left: 0;
}

@keyframes farmerWalk {
  0% {
    left: 0;
    transform: scaleX(-1);
  }

  49.9% {
    left: calc(100% - 22px);
    transform: scaleX(-1);
  }

  50% {
    left: calc(100% - 22px);
    transform: scaleX(1);
  }

  100% {
    left: 0;
    transform: scaleX(1);
  }
}

@keyframes farmerBob {
  from {
    translate: 0;
  }

  to {
    translate: 0 -2px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .farmer {
    animation: none;
  }
}

