/* [project]/app/theme.css [app-client] (css) */
:root {
  --ai: #1c2b3d;
  --ai-hover: #24374f;
  --ai-on: #8b6914;
  --ai-text: #c7bfa0;
  --ai-label: #a88f55;
  --ai-sub: #a79877;
  --bg: #f7f3e8;
  --card: #fff;
  --line: #d8be7c;
  --line-soft: #f3e3b0;
  --ink: #1c2b3d;
  --sub: #6b6459;
  --ink2: #4a4438;
  --shu: #a83b2e;
  --shu-hover: #8b2f22;
  --shu-bg: #f5e4e1;
  --live: #b85c82;
  --teal-bg: #e6eddc;
  --teal: #3c5c34;
  --blue-bg: #e2e9f0;
  --blue: #1b3a5c;
  --amber-bg: #f3e8ce;
  --amber: #8c6a0c;
  --purple-bg: #ede6f2;
  --purple: #55407a;
  --sand: #f3e3b0;
  --bar: #eae2cc;
  --off: #cfc3a6;
}

* {
  box-sizing: border-box;
}

html, body {
  height: 100%;
}

body {
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  margin: 0;
  font-family: Noto Sans JP, sans-serif;
}

h1, h2, h3, h4, p, ul, ol {
  margin: 0;
}

ul {
  padding: 0;
  list-style: none;
}

a {
  color: #a83b2e;
  text-decoration: none;
}

a:hover {
  color: #6b241c;
}

.wa {
  font-family: Zen Maru Gothic, sans-serif;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.sh {
  box-shadow: 0 1px 2px rgba(30, 38, 52, .05);
}

.ttl {
  letter-spacing: .01em;
  font-size: 19px;
  font-weight: 700;
}

.sub {
  color: var(--sub);
  font-size: 12px;
  line-height: 1.5;
}

.mut {
  color: var(--sub);
}

.chip {
  white-space: nowrap;
  border-radius: 999px;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  display: inline-flex;
}

.btn {
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--ink);
  cursor: pointer;
  white-space: nowrap;
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  gap: 7px;
  min-height: 44px;
  padding: 11px 14px;
  font: 600 13px Noto Sans JP, sans-serif;
  display: inline-flex;
}

.btn:hover {
  color: var(--ink);
  background: #f8f3e8;
}

.btn:disabled {
  opacity: .5;
  cursor: not-allowed;
}

.btn-p {
  background: var(--shu);
  border-color: var(--shu);
  color: #fff;
}

.btn-p:hover {
  background: var(--shu-hover);
  color: #fff;
}

.btn-s {
  border-radius: 8px;
  min-height: 34px;
  padding: 7px 11px;
  font-size: 12px;
}

.nav {
  color: var(--ai-text);
  border-radius: 10px;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  padding: 9px 11px;
  font-size: 13px;
  font-weight: 500;
  display: flex;
}

.nav:hover {
  background: var(--ai-hover);
  color: #fff;
}

.navon {
  background: var(--ai-on);
  color: #fff;
}

.navlbl {
  letter-spacing: .14em;
  color: var(--ai-label);
  padding: 14px 12px 5px;
  font-size: 13px;
  font-weight: 700;
}

.badge {
  background: var(--shu);
  color: #fff;
  border-radius: 999px;
  justify-content: center;
  align-items: center;
  min-width: 20px;
  height: 20px;
  margin-left: auto;
  padding: 0 6px;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
}

.num {
  font-variant-numeric: tabular-nums;
}

.mono {
  font-variant-numeric: tabular-nums;
  font-family: Consolas, Liberation Mono, monospace;
  font-size: 12px;
}

table {
  border-collapse: collapse;
  width: 100%;
}

th {
  text-align: left;
  color: var(--sub);
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
  padding: 0 10px 9px;
  font-size: 11px;
  font-weight: 700;
}

td {
  border-bottom: 1px solid var(--line-soft);
  vertical-align: middle;
  padding: 11px 10px;
  font-size: 13px;
}

input, select, textarea {
  font-family: Noto Sans JP, sans-serif;
}

.inp {
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--ink);
  border-radius: 10px;
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  font-size: 13px;
}

.avt {
  background: var(--teal-bg);
  color: var(--teal);
  border-radius: 999px;
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  font-weight: 700;
  display: flex;
}

.tab {
  color: var(--ink2);
  white-space: nowrap;
  border-radius: 9px;
  align-items: center;
  gap: 7px;
  min-height: 40px;
  padding: 9px 13px;
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
}

.tabon {
  background: var(--ai);
  color: #fff;
}

.kpi {
  font-variant-numeric: tabular-nums;
  letter-spacing: -.01em;
  font-family: Zen Maru Gothic, sans-serif;
  font-weight: 700;
}

.dot {
  border-radius: 999px;
  flex-shrink: 0;
  width: 8px;
  height: 8px;
}

.shell {
  height: 100vh;
  display: flex;
  overflow: hidden;
}

.side {
  background: var(--ai);
  flex-direction: column;
  flex-shrink: 0;
  width: 238px;
  padding: 18px 12px 14px;
  display: flex;
  overflow: auto;
}

.main {
  flex-direction: column;
  flex-grow: 1;
  min-width: 0;
  height: 100vh;
  min-height: 0;
  display: flex;
}

.topbar {
  background: var(--card);
  border-bottom: 1px solid var(--line);
  flex-shrink: 0;
  align-items: center;
  gap: 14px;
  height: 64px;
  padding: 0 24px;
  display: flex;
}

.topbar h1 {
  font-size: 22px;
  font-weight: 700;
}

.body {
  flex-direction: column;
  flex-grow: 1;
  gap: 14px;
  min-height: 0;
  padding: 20px 24px;
  display: flex;
  overflow: auto;
}

.sec {
  color: var(--ink);
  padding-top: 6px;
  font-size: 22px;
  font-weight: 700;
}

.empty {
  text-align: center;
  color: var(--sub);
  padding: 22px;
  font-size: 13px;
}

.note {
  color: var(--sub);
  background: var(--sand);
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 12px;
}

.err {
  color: var(--shu);
  background: var(--shu-bg);
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 13px;
}

.shu-tabs .tabon {
  background: var(--shu);
}

.grid3 {
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  align-items: start;
  gap: 12px;
  display: grid;
}

.topic {
  background: var(--bg);
  border-radius: 9px;
  flex-direction: column;
  gap: 3px;
  padding: 8px 10px;
  display: flex;
}

button.tab {
  border: 1px solid var(--line);
  background: var(--card);
  cursor: pointer;
  font-family: inherit;
}

button.tab.tabon {
  background: var(--ai);
  color: #fff;
  border-color: rgba(0, 0, 0, 0);
}

.shu-tabs button.tab.tabon {
  background: var(--shu);
}

button.tab:disabled {
  opacity: .5;
  cursor: not-allowed;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.spin {
  animation: .9s linear infinite spin;
}

.overlay {
  z-index: 100;
  background: rgba(28, 43, 61, .18);
  justify-content: center;
  align-items: center;
  animation: .15s ease-out fadein;
  display: flex;
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
}

@keyframes fadein {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.loader-delay {
  opacity: 0;
  animation: .2s ease-out .35s forwards fadein;
}

@keyframes bob {
  0%, 100% {
    transform: rotate(-40deg)translateY(0);
  }

  50% {
    transform: rotate(-40deg)translateY(-3px);
  }
}

.card-bob {
  transform-box: fill-box;
  transform-origin: center;
  animation: 1.1s ease-in-out infinite bob;
}

@keyframes talk {
  0%, 100% {
    box-shadow: 0 0 0 3px var(--live);
  }

  50% {
    box-shadow: 0 0 0 7px rgba(184, 92, 130, .35);
  }
}

.talking {
  animation: 1.4s ease-in-out infinite talk;
}

@media (max-width: 820px) {
  .shell {
    flex-direction: column;
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }

  .side {
    z-index: 40;
    flex-direction: row;
    align-items: center;
    gap: 4px;
    width: 100%;
    padding: 8px 10px;
    position: -webkit-sticky;
    position: sticky;
    top: 0;
    overflow-x: auto;
  }

  .side .navlbl, .side > div:first-of-type, .side > span {
    display: none;
  }

  .side .nav {
    white-space: nowrap;
    flex-shrink: 0;
    min-height: 36px;
    padding: 6px 10px;
  }

  .side .nav span:not(.badge) {
    display: inline;
  }

  .main {
    height: auto;
    min-height: 0;
  }

  .topbar {
    flex-wrap: wrap;
    gap: 8px;
    height: auto;
    min-height: 56px;
    padding: 10px 14px;
  }

  .topbar form {
    display: none !important;
  }

  .body {
    padding: 14px;
    overflow: visible !important;
  }

  .body[style*="flex-direction: row"] {
    flex-direction: column !important;
  }

  [style*="width: 300px"], [style*="width: 340px"], [style*="width: 360px"], [style*="width: 400px"], [style*="width: 440px"], [style*="width: 260px"] {
    width: 100% !important;
  }

  [style*="grid-template-columns: 1fr 1fr"], [style*="grid-template-columns: repeat(3, 1fr)"], [style*="grid-template-columns: 1.4fr 1fr 1fr"] {
    grid-template-columns: 1fr !important;
  }

  [style*="position: sticky"] {
    position: static !important;
  }

  .card[style*="flex-grow: 1"][style*="min-height: 0"] {
    min-height: 60vh;
  }
}

.noscrollbar {
  scrollbar-width: none;
}

.noscrollbar::-webkit-scrollbar {
  display: none;
}

.hoverable {
  transition: background .15s, border-color .15s, transform .15s;
}

.hoverable:hover {
  background: var(--sand);
  border-color: var(--line);
}

.map-pulse {
  transform-box: fill-box;
  transform-origin: center;
  animation: 1.4s ease-out infinite mapPulse;
}

@keyframes mapPulse {
  0% {
    opacity: 1;
    transform: scale(.85);
  }

  100% {
    opacity: 0;
    transform: scale(1.35);
  }
}

@media (prefers-reduced-motion: reduce) {
  .map-pulse {
    animation: none;
  }
}

.deck-back {
  z-index: 300;
  background: rgba(14, 20, 27, .74);
  justify-content: center;
  align-items: center;
  padding: 16px;
  animation: .35s ease-out deckIn;
  display: flex;
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
}

.deck-out {
  animation: .35s ease-in forwards deckOut;
}

@keyframes deckIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes deckOut {
  to {
    opacity: 0;
  }
}

.deck-card {
  border: 1px solid var(--line);
  transform-origin: 36px;
  background: #fffdf6;
  background-image: linear-gradient(transparent 0 58px, var(--line-soft) 58px 59px, transparent 59px);
  border-radius: 14px;
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  box-shadow: 0 10px 24px rgba(0, 0, 0, .3);
}

.deck-card:before {
  content: "";
  background: #2a323d;
  border-radius: 999px;
  width: 22px;
  height: 22px;
  position: absolute;
  top: calc(50% - 11px);
  left: 25px;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, .6);
}

.deck-top {
  -webkit-backface-visibility: visible;
  backface-visibility: visible;
  cursor: grab;
  touch-action: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
  transition: transform .25s, box-shadow .25s;
  animation: .45s ease-out deckRise;
}

.deck-top:focus-visible {
  outline-offset: 3px;
  outline: 3px solid #e0b84a;
}

@keyframes deckRise {
  from {
    opacity: .5;
    transform: rotate(3deg);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.deck-ring {
  pointer-events: none;
  position: absolute;
  top: calc(50% - 70px);
  left: -94px;
}

.deck-flip {
  box-shadow: none;
  will-change: transform, opacity;
  animation: .7s cubic-bezier(.35, .05, .35, 1) forwards deckFlip;
}

.deck-flip:after {
  content: "";
  opacity: 0;
  background: #efe8d4;
  border-radius: 14px;
  animation: .7s linear forwards deckBackside;
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
}

@keyframes deckFlip {
  from {
    opacity: 1;
    transform: perspective(1100px)rotateZ(0)rotateX(0);
  }

  to {
    opacity: .15;
    transform: perspective(1100px)rotateZ(-160deg)rotateX(180deg);
  }
}

@keyframes deckBackside {
  0%, 42% {
    opacity: 0;
  }

  52%, 100% {
    opacity: 1;
  }
}

.deck-tear {
  pointer-events: none;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, 0 51%, 9px 52.5%, 5px 50.5%, 14px 51.5%, 11px 49.5%, 20px 50.5%, 26px 50%, 20px 49.5%, 11px 48.5%, 14px 47%, 5px 48%, 9px 46%, 0 49%);
  animation: .7s ease-in forwards deckTear;
}

@keyframes deckTear {
  0% {
    transform: none;
  }

  15% {
    transform: translateX(10px)rotate(-1deg);
  }

  25% {
    transform: translateX(4px);
  }

  100% {
    opacity: 0;
    transform: translate(170px, 300px)rotate(16deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .deck-flip, .deck-flip:after, .deck-tear, .deck-top, .deck-back {
    animation-duration: 10ms;
  }
}

