}

.deck-back {
  background-image: var(--shippo-on-ai);
}

.shippo-ai {
  background-color: var(--ai);
  background-image: var(--shippo-on-ai);
}

.planter {
  background: #b5673f;
  border-radius: 16px;
  flex-direction: column;
  gap: 7px;
  min-height: 0;
  padding: 9px 9px 10px;
  display: flex;
  box-shadow: inset 0 2px rgba(255, 255, 255, .18), inset 0 -3px rgba(0, 0, 0, .18), 0 4px 10px -4px rgba(90, 50, 20, .45);
}

.planter-name {
  color: #fff6e6;
  text-shadow: 0 1px rgba(0, 0, 0, .25);
}

.planter-soil {
  background-color: #5e4330;
  background-image: radial-gradient(circle at 20% 30%, rgba(255, 235, 200, .1) 0, rgba(255, 235, 200, .1) 1.5px, rgba(0, 0, 0, 0) 2px), radial-gradient(circle at 70% 60%, rgba(0, 0, 0, .18) 0, rgba(0, 0, 0, .18) 2px, rgba(0, 0, 0, 0) 2.5px), radial-gradient(circle at 45% 85%, rgba(255, 235, 200, .08) 0, rgba(255, 235, 200, .08) 1px, rgba(0, 0, 0, 0) 1.5px);
  background-size: 23px 19px, 31px 27px, 17px 21px;
  border-radius: 10px;
  padding: 10px;
  box-shadow: inset 0 3px 8px rgba(0, 0, 0, .45);
}

.planter-soil > .card {
  background: #fffdf6;
}

.field-head {
  flex-wrap: nowrap;
  flex-shrink: 0;
  align-items: center;
  gap: 12px;
  min-height: 40px;
  display: flex;
}

.field-talk {
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  overflow: hidden;
}

.field-lane {
  border-bottom: 3px dotted #8a5a2b;
  flex: 0 0 150px;
  height: 28px;
  position: relative;
  container-type: inline-size;
}

.farmer {
  font-size: 20px;
  line-height: 1;
  animation: 7s linear infinite farmerWalk, .35s ease-in-out infinite alternate farmerBob;
  display: inline-block;
  position: absolute;
  bottom: -1px;
  left: 0;
}

@keyframes farmerWalk {
  0% {
    left: 0;
    transform: scaleX(-1);
  }

  49.9% {
    left: calc(100% - 22px);
    transform: scaleX(-1);
  }

  50% {
    left: calc(100% - 22px);
    transform: scaleX(1);
  }

  100% {
    left: 0;
    transform: scaleX(1);
  }
}

@keyframes farmerBob {
  from {
    translate: 0;
  }

  to {
    translate: 0 -2px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .farmer {
    animation: none;
  }
}

