/* [project]/app/theme.css [app-client] (css) */
:root {
  --ai: #1c2b3d;
  --ai-hover: #24374f;
  --ai-on: #8b6914;
  --ai-text: #c7bfa0;
  --ai-label: #a88f55;
  --ai-sub: #a79877;
  --bg: #f7f3e8;
  --card: #fff;
  --line: #d8be7c;
  --line-soft: #f3e3b0;
  --ink: #1c2b3d;
  --sub: #6b6459;
  --ink2: #4a4438;
  --shu: #a83b2e;
  --shu-hover: #8b2f22;
